      try{const access=await api<StudentAccessMessage>(`/enrollment/requests/${row.id}/access`,'POST',{});await whatsapp.open(studentAccessWhatsAppUrl(access));}
      catch(error){whatsapp.close();throw new Error('Aluno aprovado. Não foi possível abrir o WhatsApp: '+message(error)+'. Use Enviar acesso pelo WhatsApp para tentar novamente.');}
    }
  }
  async function sendAccess(row:EnrollmentSummary){
    const whatsapp=prepareWhatsAppWindow();
    try{const access=await api<StudentAccessMessage>(`/enrollment/requests/${row.id}/access`,'POST',{});await whatsapp.open(studentAccessWhatsAppUrl(access));}
    catch(error){whatsapp.close();throw error;}
  }
  const rows = (contacts.data ?? []).filter(
    (x) =>
      (!status || x.status === status) &&
      (!reviewOnly||!cadastro||x.id===cadastro) &&
      x.name
        .toLocaleLowerCase("pt-BR")
        .includes(search.toLocaleLowerCase("pt-BR")),
  );
  return (
    <Page>
      <Button
        variant="secondary"
        onPress={() => router.push((reviewOnly ? "/" : "/alunos") as Href)}
      >
        {reviewOnly ? "← Início" : "← Meus alunos"}
      </Button>
      <Heading
        title={reviewOnly ? "Cadastros recebidos" : "Link de Cadastro"}
        subtitle={reviewOnly ? "Confira a ficha e aprove ou recuse cada solicitação." : "Receba fichas e aprove cada novo acompanhamento."}
      />
      {reviewOnly&&!!cadastro&&<Button variant="secondary" onPress={()=>router.replace('/alunos/cadastros')}>Ver todos os cadastros recebidos</Button>}
      {!reviewOnly && <Choices
        label="Seção"
        value={tab}
        onChange={setTab}
        options={["Link", "Contatos"].map((value) => ({ value, label: value }))}
      />}
      <Notice error>{error || link.error || contacts.error}</Notice>
      <Notice>{feedback}</Notice>
      {!reviewOnly && tab === "Link" ? (
        <Card>
          <ChainIcon />
          <Label size={22} bold>
            Seu próximo aluno começa aqui
          </Label>
          <Label>
            Compartilhe o formulário para receber os dados diretamente no seu
            painel. Cada cadastro aguarda sua aprovação.
          </Label>
          <Notice>
            {contacts.data?.length ?? 0} cadastros recebidos ·{" "}
            {contacts.data?.filter((x) => x.status === "pending").length ?? 0}{" "}
            pendentes
          </Notice>
          {link.data ? (
            <>
              <Badge>
                {link.data.active ? "Link ativo" : "Link desativado"}
              </Badge>
              <Field
                label="URL de cadastro"
                value={link.data.url}
                editable={false}
                selectTextOnFocus
              />
              <Label muted>
                Responsável: {link.data.publicName} · Contato:{" "}
                {link.data.contact}
              </Label>
              {link.data.local && (
                <Notice>
                  Modo local: este endereço funciona no computador que executa o
                  Tá Pago. Para acesso por outro dispositivo, configure o
                  endereço da rede local.
                </Notice>
              )}
              <View style={s.row}>
                <Button
                  disabled={busy || !link.data.active}
                  onPress={() =>
                    void action(
                      () => copyEnrollmentLink(link.data!.url),
                      "Link copiado.",
                    )
                  }
                >
                  Copiar link
                </Button>
                <Button
                  disabled={busy || !link.data.active}
                  variant="secondary"
                  onPress={() =>
                    void action(() => whatsappEnrollment(link.data!.url))
                  }
                >
                  Enviar pelo WhatsApp
                </Button>
                <Button
                  disabled={busy || !link.data.active}
                  variant="secondary"
                  onPress={() =>
                    void action(async () =>
                      setFeedback(await shareEnrollmentLink(link.data!.url)),
                    )
                  }
                >
                  Compartilhar
                </Button>
                <Button
                  disabled={!link.data.active}
                  variant="secondary"
                  onPress={() =>
                    void action(() => Linking.openURL(link.data!.url))
                  }
                >
                  Visualizar formulário
                </Button>
              </View>
              <View style={{ marginTop: 20 }}>
                {link.data.active && (
                  <Button
                    variant="danger"
                    onPress={() =>
                      setConfirmation({
                        title: "Desativar link",
                        description:
                          "O formulário deixará de aceitar novos cadastros. As fichas recebidas serão preservadas.",
                        run: async () => {
                          await api("/enrollment/link", "DELETE");
                          await reload();
                        },
                      })
                    }
                  >
                    Desativar link
                  </Button>
                )}
              </View>
            </>
          ) : (
            <Notice>
              Defina seu nome público e um contato para dúvidas sobre a ficha.
              Ambos aparecerão no formulário.
            </Notice>
          )}
          <View style={{ marginTop: 24 }}>
            <Field
              label="Nome público do personal"
              value={name}
              onChangeText={setName}
            />
            <Field
              label="Contato público para privacidade (e-mail ou telefone)"
              value={contact}
              onChangeText={setContact}
            />
            <Button
              disabled={busy || !name.trim() || !contact.trim()}
              onPress={() => {
                const run = async () => {
                  await api("/enrollment/link", "POST", {
                    publicName: name,
                    contact,
                  });
                  await reload();
                };
                if (link.data)
                  setConfirmation({
                    title: "Gerar novo link",
                    description:
                      "O endereço anterior será invalidado imediatamente. Os cadastros já recebidos serão preservados.",
                    run,
                  });
                else void action(run, "Link criado.");
              }}
            >
              {link.data ? "Gerar novo link" : "Gerar meu link"}
            </Button>
          </View>
        </Card>
      ) : (
        <>
          {!reviewOnly && <Field
            label="Buscar cadastro por nome"
            value={search}
            onChangeText={setSearch}
          />}
          {!reviewOnly && <Choices
            label="Status do relacionamento"
            value={status}
            onChange={setStatus}
            options={[
              { value: "", label: "Todos" },
              ...Object.entries(enrollmentStatus).map(([value, label]) => ({
                value,
                label,
              })),
            ]}
          />}
