          >
            {readonly ? (
              <Label>{answers[q.id] || "Sem resposta"}</Label>
            ) : q.type === "choice" ? (
              <Choices
                label={`Resposta ${q.position}`}
                value={answers[q.id] ?? ""}
                onChange={(value) => setAnswers({ ...answers, [q.id]: value })}
                options={q.options.map((o) => ({
                  value: o.label,
                  label: o.label,
                }))}
              />
            ) : (
              <Field
                label={
                  q.type === "text"
                    ? "Resposta livre"
                    : `Resposta numérica (${q.min ?? "sem mínimo"} a ${q.max ?? "sem máximo"})`
                }
                value={answers[q.id] ?? ""}
                onChangeText={(value) =>
