      <Notice error>{error}</Notice>
      <Notice>{saved}</Notice>
      {!readonly && (
        <View style={s.row}>
          <Button
            variant="secondary"
            disabled={busy}
            onPress={() => {
              void save("rascunho").catch(() => {});
            }}
          >
            {studentView ? "Salvar respostas" : "Salvar rascunho"}
          </Button>
          {!studentView && (
            <Button disabled={busy} onPress={() => setConfirm(true)}>
              Concluir avaliação
            </Button>
          )}
        </View>
