{"behavior":[{"confidence":"observed","description":"Contém JSX que referencia Button, Card, Choices, Field, Label, Notice, View; a execução visual não foi testada.","evidence":[{"end_line":174,"snippet":"export function TemplateForm({
  template,
  onSaved,
}: {
  template?: Template;
  onSaved: () => void;
}) {
  const [name, setName] = useState(template?.name ?? "");
  const [cycle, setCycle] = useState(String(template?.cycleDays ?? 30));
  const [questions, setQuestions] = useState<Question[]>(
    template?.questions.map((q) => ({
      ...q,
      options: q.options.map((o) => o.label).join("\n"),
      min: q.min === null ? "" : String(q.min),
      max: q.max === null ? "" : String(q.max),
    })) ?? [blank()],
  );
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  function update(i: number, part: Partial<Question>) {
    setQuestions((q) => q.map((x, j) => (i === j ? { ...x, ...part } : x)));
  }
  async function save() {
    setError("");
    const parsed = templateSchema.safeParse({
      name,
      cycleDays: Number(cycle),
      questions: questions.map((q) => ({
        ...q,
        options:
          q.type === "choice"
            ? q.options
                .split("\n")
                .map((x) => x.trim())
                .filter(Boolean)
                .map((label) => ({ label }))
            : [],
        min: q.min === "" ? null : Number(q.min),
        max: q.max === "" ? null : Number(q.max),
      })),
    });
    if (!parsed.success) {
      setError(parsed.error.issues.map((i) => i.message).join("; "));
      return;
    }
    setBusy(true);
    try {
      await api("/templates", "POST", parsed.data);
      onSaved();
    } catch (e) {
      setError(message(e));
    } finally {
      setBusy(false);
    }
  }
