export default function EnrollmentLinkPage({ reviewOnly = false }: { reviewOnly?: boolean } = {}) {
  const {cadastro}=useLocalSearchParams<{cadastro?:string}>();
  const { user } = useSession();
  const link = useResource<LinkInfo | null>(reviewOnly ? null : "/enrollment/link");
  const contacts = useResource<EnrollmentSummary[]>("/enrollment/requests");
  const [tab, setTab] = useState(reviewOnly ? "Contatos" : "Link"),
    [name, setName] = useState(user?.name ?? ""),
    [contact, setContact] = useState(""),
    [search, setSearch] = useState(""),
    [status, setStatus] = useState(reviewOnly ? "pending" : ""),
    [feedback, setFeedback] = useState(""),
    [error, setError] = useState(""),
    [busy, setBusy] = useState(false),
    [detail, setDetail] = useState<EnrollmentDetail | null>(null),
    [confirmation, setConfirmation] = useState<{
      title: string;
      description: string;
      run: () => Promise<void>;
    } | null>(null);
  useEffect(() => {
    if (link.data) {
      setName(link.data.publicName);
      setContact(link.data.contact);
    }
  }, [link.data]);
  useEffect(() => {
    const timer = setInterval(() => void contacts.reload(), 15000);
    return () => clearInterval(timer);
  }, [contacts.reload]);
  async function action(run: () => Promise<unknown>, success?: string) {
    setBusy(true);
    setError("");
    setFeedback("");
    try {
      await run();
      if (success) setFeedback(success);
    } catch (e) {
      if ((e as Error).name !== "AbortError") setError(message(e));
    } finally {
      setBusy(false);
    }
  }
  async function reload() {
    await Promise.all([contacts.reload(), link.reload()]);
  }
  async function change(
    row: EnrollmentSummary | EnrollmentDetail,
    status: string,
  ) {
    const whatsapp=status==='active'?prepareWhatsAppWindow():null;
    try{
      await api(`/enrollment/requests/${row.id}/status`, "POST", { status });
    }catch(error){whatsapp?.close();throw error;}
    setDetail(null);
    await reload();
    if(whatsapp){
      try{const access=await api<StudentAccessMessage>(`/enrollment/requests/${row.id}/access`,'POST',{});await whatsapp.open(studentAccessWhatsAppUrl(access));}
      catch(error){whatsapp.close();throw new Error('Aluno aprovado. Não foi possível abrir o WhatsApp: '+message(error)+'. Use Enviar acesso pelo WhatsApp para tentar novamente.');}
    }
  }
  async function sendAccess(row:EnrollmentSummary){
    const whatsapp=prepareWhatsAppWindow();
    try{const access=await api<StudentAccessMessage>(`/enrollment/requests/${row.id}/access`,'POST',{});await whatsapp.open(studentAccessWhatsAppUrl(access));}
    catch(error){whatsapp.close();throw error;}
  }
  const rows = (contacts.data ?? []).filter(
    (x) =>
      (!status || x.status === status) &&
      (!reviewOnly||!cadastro||x.id===cadastro) &&
      x.name
        .toLocaleLowerCase("pt-BR")
        .includes(search.toLocaleLowerCase("pt-BR")),
  );
  return (
    <Page>
      <Button
        variant="secondary"
        onPress={() => router.push((reviewOnly ? "/" : "/alunos") as Href)}
      >
        {reviewOnly ? "← Início" : "← Meus alunos"}
      </Button>
      <Heading
        title={reviewOnly ? "Cadastros recebidos" : "Link de Cadastro"}
        subtitle={reviewOnly ? "Confira a ficha e aprove ou recuse cada solicitação." : "Receba fichas e aprove cada novo acompanhamento."}
      />
      {reviewOnly&&!!cadastro&&<Button variant="secondary" onPress={()=>router.replace('/alunos/cadastros')}>Ver todos os cadastros recebidos</Button>}
      {!reviewOnly && <Choices
        label="Seção"
        value={tab}
        onChange={setTab}
        options={["Link", "Contatos"].map((value) => ({ value, label: value }))}
      />}
      <Notice error>{error || link.error || contacts.error}</Notice>
      <Notice>{feedback}</Notice>
      {!reviewOnly && tab === "Link" ? (
        <Card>
          <ChainIcon />
          <Label size={22} bold>
            Seu próximo aluno começa aqui
          </Label>
          <Label>
            Compartilhe o formulário para receber os dados diretamente no seu
            painel. Cada cadastro aguarda sua aprovação.
          </Label>
          <Notice>
            {contacts.data?.length ?? 0} cadastros recebidos ·{" "}
            {contacts.data?.filter((x) => x.status === "pending").length ?? 0}{" "}
            pendentes
          </Notice>
          {link.data ? (
            <>
              <Badge>
                {link.data.active ? "Link ativo" : "Link desativado"}
              </Badge>
              <Field
                label="URL de cadastro"
                value={link.data.url}
                editable={false}
                selectTextOnFocus
              />
              <Label muted>
                Responsável: {link.data.publicName} · Contato:{" "}
                {link.data.contact}
              </Label>
              {link.data.local && (
                <Notice>
                  Modo local: este endereço funciona no computador que executa o
                  Tá Pago. Para acesso por outro dispositivo, configure o
                  endereço da rede local.
                </Notice>
              )}
              <View style={s.row}>
                <Button
                  disabled={busy || !link.data.active}
                  onPress={() =>
                    void action(
                      () => copyEnrollmentLink(link.data!.url),
                      "Link copiado.",
                    )
                  }
                >
                  Copiar link
                </Button>
                <Button
                  disabled={busy || !link.data.active}
                  variant="secondary"
                  onPress={() =>
                    void action(() => whatsappEnrollment(link.data!.url))
                  }
                >
                  Enviar pelo WhatsApp
                </Button>
                <Button
                  disabled={busy || !link.data.active}
                  variant="secondary"
                  onPress={() =>
                    void action(async () =>
                      setFeedback(await shareEnrollmentLink(link.data!.url)),
                    )
                  }
                >
                  Compartilhar
                </Button>
                <Button
                  disabled={!link.data.active}
                  variant="secondary"
                  onPress={() =>
                    void action(() => Linking.openURL(link.data!.url))
                  }
                >
                  Visualizar formulário
                </Button>
              </View>
              <View style={{ marginTop: 20 }}>
                {link.data.active && (
                  <Button
                    variant="danger"
                    onPress={() =>
                      setConfirmation({
                        title: "Desativar link",
                        description:
                          "O formulário deixará de aceitar novos cadastros. As fichas recebidas serão preservadas.",
                        run: async () => {
                          await api("/enrollment/link", "DELETE");
                          await reload();
                        },
                      })
                    }
                  >
                    Desativar link
                  </Button>
                )}
              </View>
            </>
          ) : (
            <Notice>
              Defina seu nome público e um contato para dúvidas sobre a ficha.
              Ambos aparecerão no formulário.
            </Notice>
          )}
          <View style={{ marginTop: 24 }}>
            <Field
              label="Nome público do personal"
              value={name}
              onChangeText={setName}
            />
            <Field
              label="Contato público para privacidade (e-mail ou telefone)"
              value={contact}
              onChangeText={setContact}
            />
            <Button
              disabled={busy || !name.trim() || !contact.trim()}
              onPress={() => {
                const run = async () => {
                  await api("/enrollment/link", "POST", {
                    publicName: name,
                    contact,
                  });
                  await reload();
                };
                if (link.data)
                  setConfirmation({
                    title: "Gerar novo link",
                    description:
                      "O endereço anterior será invalidado imediatamente. Os cadastros já recebidos serão preservados.",
                    run,
                  });
                else void action(run, "Link criado.");
              }}
            >
              {link.data ? "Gerar novo link" : "Gerar meu link"}
            </Button>
          </View>
        </Card>
      ) : (
        <>
          {!reviewOnly && <Field
            label="Buscar cadastro por nome"
            value={search}
            onChangeText={setSearch}
          />}
          {!reviewOnly && <Choices
            label="Status do relacionamento"
            value={status}
            onChange={setStatus}
            options={[
              { value: "", label: "Todos" },
              ...Object.entries(enrollmentStatus).map(([value, label]) => ({
                value,
                label,
              })),
            ]}
          />}
          {contacts.loading ? (
            <Notice>Carregando cadastros…</Notice>
          ) : !rows.length ? (
            <Notice>{reviewOnly ? "Nenhum cadastro aguardando aprovação." : "Nenhum cadastro encontrado."}</Notice>
          ) : (
            rows.map((row) => (
              <Card key={row.id}>
                <View style={[s.row, { justifyContent: "space-between" }]}>
                  <Label size={20} bold>
                    {row.name}
                  </Label>
                  <Badge>{enrollmentStatus[row.status]}</Badge>
                </View>
                <Label muted>
                  {formatDate(row.createdAt)} · {row.goals.join(", ")}
                </Label>
                <Label>
                  {row.email} · {row.phone}
                </Label>
                <View style={[s.row, { marginTop: 14 }]}>
                  <Button
                    variant="secondary"
                    onPress={() =>
                      void action(async () =>
                        setDetail(
                          await api<EnrollmentDetail>(
                            `/enrollment/requests/${row.id}`,
                          ),
                        ),
                      )
                    }
                  >
                    Ver ficha
                  </Button>
                  {row.status === "pending" && (
                    <>
                      <Button
                        disabled={busy}
                        onPress={() =>
                          void action(
                            () => change(row, "active"),
                            "Aluno aprovado.",
                          )
                        }
                      >
                        Aprovar
                      </Button>
                      <Button
                        variant="danger"
                        onPress={() =>
                          setConfirmation({
                            title: "Recusar cadastro",
                            description:
                              "A solicitação será marcada como recusada. Nenhuma conta será criada.",
                            run: () => change(row, "rejected"),
                          })
                        }
                      >
                        Recusar
                      </Button>
                    </>
                  )}
                  {row.status === "active" && (
                    <>
                      <Button variant="secondary" disabled={busy} onPress={()=>void action(()=>sendAccess(row))}>Enviar acesso pelo WhatsApp</Button>
                      <Button
                        variant="secondary"
                        onPress={() =>
                          router.push(`/alunos/${row.studentId}` as Href)
                        }
                      >
                        Abrir acompanhamento
                      </Button>
                      <Button
                        variant="danger"
                        onPress={() =>
                          setConfirmation({
                            title: "Desativar vínculo",
                            description:
                              "Seu acesso ao acompanhamento será encerrado. O histórico da conta do aluno será preservado.",
                            run: () => change(row, "inactive"),
                          })
                        }
                      >
                        Desativar vínculo
                      </Button>
                    </>
                  )}
                </View>
              </Card>
            ))
          )}
        </>
      )}
      {detail && (
        <Dialog title="Ficha cadastral" onClose={() => setDetail(null)}>
          <EnrollmentSummaryView form={detail.form} />
          <Notice>
            Política {detail.policyVersion} · Autorização em{" "}
            {formatDate(detail.consentAt)} · Saúde:{" "}
            {detail.healthConsentAt ? "autorizada" : "não autorizada"}
          </Notice>
          <Label bold>Histórico de status</Label>
          {detail.events.map((event, i) => (
            <Label key={i}>
              {formatDate(event.createdAt)} · {enrollmentStatus[event.status]}
            </Label>
          ))}
          {detail.status !== "active" && (
            <Button
              variant="danger"
              onPress={() =>
                setConfirmation({
                  title: "Excluir ficha",
                  description:
                    "Exclui definitivamente a solicitação, seus consentimentos e informações de saúde. Um acompanhamento existente não será apagado por esta ação.",
                  run: async () => {
                    await api(`/enrollment/requests/${detail.id}`, "DELETE");
                    setDetail(null);
                    await reload();
                  },
                })
              }
            >
              Excluir ficha
            </Button>
          )}
        </Dialog>
      )}
      {confirmation && (
        <Confirm
          title={confirmation.title}
          description={confirmation.description}
          onConfirm={confirmation.run}
          onClose={() => setConfirmation(null)}
        />
      )}
    </Page>
  );
}

export default function EnrollmentLinkPage({ reviewOnly = false }: { reviewOnly?: boolean } = {}) {
  const {cadastro}=useLocalSearchParams<{cadastro?:string}>();
  const { user } = useSession();
  const link = useResource<LinkInfo | null>(reviewOnly ? null : "/enrollment/link");
  const contacts = useResource<EnrollmentSummary[]>("/enrollment/requests");
  const [tab, setTab] = useState(reviewOnly ? "Contatos" : "Link"),
    [name, setName] = useState(user?.name ?? ""),
    [contact, setContact] = useState(""),
    [search, setSearch] = useState(""),
    [status, setStatus] = useState(reviewOnly ? "pending" : ""),
    [feedback, setFeedback] = useState(""),
    [error, setError] = useState(""),
    [busy, setBusy] = useState(false),
    [detail, setDetail] = useState<EnrollmentDetail | null>(null),
    [confirmation, setConfirmation] = useState<{
      title: string;
      description: string;
      run: () => Promise<void>;
    } | null>(null);
  useEffect(() => {
    if (link.data) {
      setName(link.data.publicName);
      setContact(link.data.contact);
    }
  }, [link.data]);
  useEffect(() => {
    const timer = setInterval(() => void contacts.reload(), 15000);
    return () => clearInterval(timer);
  }, [contacts.reload]);
  async function action(run: () => Promise<unknown>, success?: string) {
    setBusy(true);
    setError("");
    setFeedback("");
    try {
      await run();
      if (success) setFeedback(success);
    } catch (e) {
      if ((e as Error).name !== "AbortError") setError(message(e));
    } finally {
      setBusy(false);
    }
  }
  async function reload() {
    await Promise.all([contacts.reload(), link.reload()]);
  }
  async function change(
    row: EnrollmentSummary | EnrollmentDetail,
    status: string,
  ) {
    const whatsapp=status==='active'?prepareWhatsAppWindow():null;
    try{
      await api(`/enrollment/requests/${row.id}/status`, "POST", { status });
    }catch(error){whatsapp?.close();throw error;}
    setDetail(null);
    await reload();
    if(whatsapp){
      try{const access=await api<StudentAccessMessage>(`/enrollment/requests/${row.id}/access`,'POST',{});await whatsapp.open(studentAccessWhatsAppUrl(access));}
      catch(error){whatsapp.close();throw new Error('Aluno aprovado. Não foi possível abrir o WhatsApp: '+message(error)+'. Use Enviar acesso pelo WhatsApp para tentar novamente.');}
    }
  }
  async function sendAccess(row:EnrollmentSummary){
    const whatsapp=prepareWhatsAppWindow();
    try{const access=await api<StudentAccessMessage>(`/enrollment/requests/${row.id}/access`,'POST',{});await whatsapp.open(studentAccessWhatsAppUrl(access));}
    catch(error){whatsapp.close();throw error;}
  }
  const rows = (contacts.data ?? []).filter(
    (x) =>
      (!status || x.status === status) &&
      (!reviewOnly||!cadastro||x.id===cadastro) &&
      x.name
        .toLocaleLowerCase("pt-BR")
        .includes(search.toLocaleLowerCase("pt-BR")),
  );
  return (
    <Page>
      <Button
        variant="secondary"
        onPress={() => router.push((reviewOnly ? "/" : "/alunos") as Href)}
      >
        {reviewOnly ? "← Início" : "← Meus alunos"}
      </Button>
      <Heading
        title={reviewOnly ? "Cadastros recebidos" : "Link de Cadastro"}
        subtitle={reviewOnly ? "Confira a ficha e aprove ou recuse cada solicitação." : "Receba fichas e aprove cada novo acompanhamento."}
      />
      {reviewOnly&&!!cadastro&&<Button variant="secondary" onPress={()=>router.replace('/alunos/cadastros')}>Ver todos os cadastros recebidos</Button>}
      {!reviewOnly && <Choices
        label="Seção"
        value={tab}
        onChange={setTab}
        options={["Link", "Contatos"].map((value) => ({ value, label: value }))}
      />}
      <Notice error>{error || link.error || contacts.error}</Notice>
      <Notice>{feedback}</Notice>
      {!reviewOnly && tab === "Link" ? (
        <Card>
          <ChainIcon />
          <Label size={22} bold>
            Seu próximo aluno começa aqui
          </Label>
          <Label>
            Compartilhe o formulário para receber os dados diretamente no seu
            painel. Cada cadastro aguarda sua aprovação.
          </Label>
          <Notice>
            {contacts.data?.length ?? 0} cadastros recebidos ·{" "}
            {contacts.data?.filter((x) => x.status === "pending").length ?? 0}{" "}
            pendentes
          </Notice>
          {link.data ? (
            <>
              <Badge>
                {link.data.active ? "Link ativo" : "Link desativado"}
              </Badge>
              <Field
                label="URL de cadastro"
                value={link.data.url}
                editable={false}
                selectTextOnFocus
              />
              <Label muted>
                Responsável: {link.data.publicName} · Contato:{" "}
                {link.data.contact}
              </Label>
              {link.data.local && (
                <Notice>
                  Modo local: este endereço funciona no computador que executa o
                  Tá Pago. Para acesso por outro dispositivo, configure o
                  endereço da rede local.
                </Notice>
              )}
              <View style={s.row}>
                <Button
                  disabled={busy || !link.data.active}
                  onPress={() =>
                    void action(
                      () => copyEnrollmentLink(link.data!.url),
                      "Link copiado.",
                    )
                  }
                >
                  Copiar link
                </Button>
                <Button
                  disabled={busy || !link.data.active}
                  variant="secondary"
                  onPress={() =>
                    void action(() => whatsappEnrollment(link.data!.url))
                  }
                >
                  Enviar pelo WhatsApp
                </Button>
                <Button
                  disabled={busy || !link.data.active}
                  variant="secondary"
                  onPress={() =>
                    void action(async () =>
                      setFeedback(await shareEnrollmentLink(link.data!.url)),
                    )
                  }
                >
                  Compartilhar
                </Button>
                <Button
                  disabled={!link.data.active}
                  variant="secondary"
                  onPress={() =>
                    void action(() => Linking.openURL(link.data!.url))
                  }
                >
                  Visualizar formulário
                </Button>
              </View>
              <View style={{ marginTop: 20 }}>
                {link.data.active && (
                  <Button
                    variant="danger"
                    onPress={() =>
                      setConfirmation({
                        title: "Desativar link",
                        description:
                          "O formulário deixará de aceitar novos cadastros. As fichas recebidas serão preservadas.",
                        run: async () => {
                          await api("/enrollment/link", "DELETE");
                          await reload();
                        },
                      })
                    }
                  >
                    Desativar link
                  </Button>
                )}
              </View>
            </>
          ) : (
            <Notice>
              Defina seu nome público e um contato para dúvidas sobre a ficha.
              Ambos aparecerão no formulário.
            </Notice>
          )}
          <View style={{ marginTop: 24 }}>
            <Field
              label="Nome público do personal"
              value={name}
              onChangeText={setName}
            />
            <Field
              label="Contato público para privacidade (e-mail ou telefone)"
              value={contact}
              onChangeText={setContact}
            />
            <Button
              disabled={busy || !name.trim() || !contact.trim()}
              onPress={() => {
                const run = async () => {
                  await api("/enrollment/link", "POST", {
                    publicName: name,
                    contact,
                  });
                  await reload();
                };
                if (link.data)
                  setConfirmation({
                    title: "Gerar novo link",
                    description:
                      "O endereço anterior será invalidado imediatamente. Os cadastros já recebidos serão preservados.",
                    run,
                  });
                else void action(run, "Link criado.");
              }}
            >
              {link.data ? "Gerar novo link" : "Gerar meu link"}
            </Button>
          </View>
        </Card>
      ) : (
        <>
          {!reviewOnly && <Field
            label="Buscar cadastro por nome"
            value={search}
            onChangeText={setSearch}
          />}
          {!reviewOnly && <Choices
            label="Status do relacionamento"
            value={status}
            onChange={setStatus}
            options={[
              { value: "", label: "Todos" },
              ...Object.entries(enrollmentStatus).map(([value, label]) => ({
                value,
                label,
              })),
            ]}
          />}
          {contacts.loading ? (
            <Notice>Carregando cadastros…</Notice>
          ) : !rows.length ? (
            <Notice>{reviewOnly ? "Nenhum cadastro aguardando aprovação." : "Nenhum cadastro encontrado."}</Notice>
          ) : (
            rows.map((row) => (
              <Card key={row.id}>
                <View style={[s.row, { justifyContent: "space-between" }]}>
                  <Label size={20} bold>
                    {row.name}
                  </Label>
                  <Badge>{enrollmentStatus[row.status]}</Badge>
                </View>
                <Label muted>
                  {formatDate(row.createdAt)} · {row.goals.join(", ")}
                </Label>
                <Label>
                  {row.email} · {row.phone}
                </Label>
                <View style={[s.row, { marginTop: 14 }]}>
                  <Button
                    variant="secondary"
                    onPress={() =>
                      void action(async () =>
                        setDetail(
                          await api<EnrollmentDetail>(
                            `/enrollment/requests/${row.id}`,
                          ),
                        ),
                      )
                    }
                  >
                    Ver ficha
                  </Button>
                  {row.status === "pending" && (
                    <>
                      <Button
                        disabled={busy}
                        onPress={() =>
                          void action(
                            () => change(row, "active"),
                            "Aluno aprovado.",
                          )
                        }
                      >
                        Aprovar
                      </Button>
                      <Button
                        variant="danger"
                        onPress={() =>
                          setConfirmation({
                            title: "Recusar cadastro",
                            description:
                              "A solicitação será marcada como recusada. Nenhuma conta será criada.",
                            run: () => change(row, "rejected"),
                          })
                        }
                      >
                        Recusar
                      </Button>
                    </>
                  )}
                  {row.status === "active" && (
                    <>
                      <Button variant="secondary" disabled={busy} onPress={()=>void action(()=>sendAccess(row))}>Enviar acesso pelo WhatsApp</Button>
                      <Button
                        variant="secondary"
                        onPress={() =>
                          router.push(`/alunos/${row.studentId}` as Href)
                        }
                      >
                        Abrir acompanhamento
                      </Button>
                      <Button
                        variant="danger"
                        onPress={() =>
                          setConfirmation({
                            title: "Desativar vínculo",
                            description:
                              "Seu acesso ao acompanhamento será encerrado. O histórico da conta do aluno será preservado.",
                            run: () => change(row, "inactive"),
                          })
                        }
                      >
                        Desativar vínculo
                      </Button>
                    </>
                  )}
                </View>
              </Card>
            ))
          )}
        </>
      )}
      {detail && (
        <Dialog title="Ficha cadastral" onClose={() => setDetail(null)}>
          <EnrollmentSummaryView form={detail.form} />
          <Notice>
            Política {detail.policyVersion} · Autorização em{" "}
            {formatDate(detail.consentAt)} · Saúde:{" "}
            {detail.healthConsentAt ? "autorizada" : "não autorizada"}
          </Notice>
          <Label bold>Histórico de status</Label>
          {detail.events.map((event, i) => (
            <Label key={i}>
              {formatDate(event.createdAt)} · {enrollmentStatus[event.status]}
            </Label>
          ))}
          {detail.status !== "active" && (
            <Button
              variant="danger"
              onPress={() =>
                setConfirmation({
                  title: "Excluir ficha",
                  description:
                    "Exclui definitivamente a solicitação, seus consentimentos e informações de saúde. Um acompanhamento existente não será apagado por esta ação.",
                  run: async () => {
                    await api(`/enrollment/requests/${detail.id}`, "DELETE");
                    setDetail(null);
                    await reload();
                  },
                })
              }
            >
              Excluir ficha
            </Button>
          )}
        </Dialog>
      )}
      {confirmation && (
        <Confirm
          title={confirmation.title}
          description={confirmation.description}
          onConfirm={confirmation.run}
          onClose={() => setConfirmation(null)}
        />
      )}
    </Page>
  );
}

export default function ActivateStudent(){
  const {convite}=useLocalSearchParams<{convite:string}>(),{authenticate}=useSession();
  const [info,setInfo]=useState<{name:string;email:string;existingAccount:boolean}|null>(null);
  const [password,setPassword]=useState(''),[confirmation,setConfirmation]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);
  useEffect(()=>{let alive=true;setInfo(null);setError('');api<typeof info>(`/public/student-access/${encodeURIComponent(convite??'')}`).then(result=>{if(alive)setInfo(result);}).catch(e=>{if(alive)setError(message(e));});return()=>{alive=false;};},[convite]);
  async function submit(){
    if(!info)return;
    if(!info.existingAccount&&!passwordHasMinimum(password)){setError(PASSWORD_MINIMUM_MESSAGE);return;}
    if(!info.existingAccount&&password!==confirmation){setError('A confirmação deve ser igual à senha.');return;}
    setBusy(true);setError('');
    try{
      if(!info.existingAccount)await api(`/public/student-access/${encodeURIComponent(convite)}`,'POST',{password});
      await authenticate('login',{email:info.email,password});
      if(info.existingAccount)await api('/me/claim','POST',{code:convite});
      router.replace('/');
    }catch(e){setError(message(e));}finally{setBusy(false);}
  }
  return <Page><View style={{maxWidth:520,width:'100%',alignSelf:'center',gap:20}}><Brand/><Card>
    <Label size={24} bold>Seu acesso ao Tá Pago</Label><Notice error>{error}</Notice>
    {info&&<><Label>Olá, {info.name}! Seu cadastro foi aprovado.</Label><Field label="E-mail de acesso" value={info.email} editable={false}/>
      <Label>{info.existingAccount?'Entre com a senha da sua conta para conectar seu acompanhamento.':'Defina sua senha para acessar seus treinos e seu acompanhamento.'}</Label>
      <PasswordField label={info.existingAccount?'Sua senha':'Crie sua senha'} value={password} onChangeText={setPassword} autoComplete={info.existingAccount?'current-password':'new-password'}/>
      {!info.existingAccount&&<><Label size={12} muted>Mínimo de 6 caracteres. Pode usar letras, números ou símbolos.</Label><PasswordField label="Confirme sua senha" value={confirmation} onChangeText={setConfirmation} autoComplete="new-password"/></>}
      <Button disabled={busy} onPress={()=>void submit()}>{busy?'Aguarde…':info.existingAccount?'Entrar e conectar':'Ativar meu acesso'}</Button></>}
  </Card></View></Page>;
}

