    setLoading(true);
    setError("");
    setInfo(null);
    setSent(false);
    setForm(initial);
    setStep(0);
    api<PublicEnrollment>(`/public/enrollment/${encodeURIComponent(token)}`)
      .then(setInfo)
      .catch((e) => setError(message(e)))
      .finally(() => setLoading(false));
  }, [token]);
  const field = (
    key: keyof EnrollmentInput,
    label: string,
    extra: object = {},
  ) => (
    <FormattedField
      label={label}
      format={key === "birthDate" ? "date" : key === "phone" ? "phone" : undefined}
      value={String(form[key] ?? "")}
      onChangeText={(value) => setForm({ ...form, [key]: value })}
      {...extra}
    />
  );
  function next() {
    const parsed = enrollmentSchema.safeParse({ ...form, consent: true });
    const keys = [
      ["name", "email", "phone", "birthDate", "city", "state", "gender"],
      ["goals", "specificGoals"],
      [
        "practicing",
        "daysPerWeek",
        "experienceDuration",
        "previousTrainer",
        "preferredActivity",
        "availability",
      ],
      ["health", "healthConsent"],
    ][step];
