export function Fields({
  fields,
  values,
  setValues,
}: {
  fields: Descriptor[];
  values: Record<string, string>;
  setValues: (v: Record<string, string>) => void;
}) {
  return (
    <>
      {fields.map((f) =>
        f.options ? (
          <Choices
            key={f.key}
            label={f.label}
            options={f.options.map((value) => ({ value, label: value }))}
            value={values[f.key] ?? f.options[0]}
            onChange={(value) => setValues({ ...values, [f.key]: value })}
          />
        ) : (
          <FormattedField
            key={f.key}
            label={f.label + (f.required ? " *" : "")}
            value={values[f.key] ?? ""}
            onChangeText={(value) => setValues({ ...values, [f.key]: value })}
            multiline={f.type === "textarea"}
            keyboardType={
              f.type === "number"
                ? "decimal-pad"
                : f.type === "email"
                  ? "email-address"
                  : "default"
            }
            format={f.type === "date" ? "date" : f.type === "tel" ? "phone" : undefined}
          />
        ),
      )}
    </>
  );
}

