    if (!data.success) {
      setError(data.error.issues.map((i) => i.message).join("; "));
      return;
    }
    setBusy(true);
    try {
      onSaved(
        await api<Student>(
          student ? `/students/${student.id}` : "/students",
          student ? "PUT" : "POST",
          data.data,
        ),
      );
    } catch (e) {
      setError(message(e));
    } finally {
      setBusy(false);
    }
  }
