function RecordList({
  records,
  readonly,
  onAdd,
  onEdit,
  onDelete,
}: {
  records: TrackingRecord[];
  readonly: boolean;
  onAdd: () => void;
  onEdit: (r: TrackingRecord) => void;
  onDelete: (r: TrackingRecord) => void;
}) {
  const [expanded, setExpanded] = useState("");
  if (!records.length)
    return (
      <Empty
        title="Nenhum registro neste período"
        description="Os próximos registros formarão o histórico de evolução."
        action={
          !readonly ? (
            <Button variant="secondary" onPress={onAdd}>
              Adicionar registro
            </Button>
          ) : undefined
        }
      />
    );
  return (
    <>
      {records.map((r) => (
        <Section
          key={r.id}
          title={`${formatDate(r.date)}${r.kind === "monthly" ? ` · Ciclo ${r.data.cycle}` : ""}`}
        >
          <RecordValues record={r} />
          {r.kind === "technical" && (
            <>
              <Button
                variant="secondary"
                onPress={() => setExpanded(expanded === r.id ? "" : r.id)}
              >
                Ver os 13 critérios
              </Button>
              {expanded === r.id &&
                (r.data.criteria as Criterion[]).map((c) => (
                  <Card key={c.criterion}>
                    <Label bold>{c.criterion}</Label>
                    {[
                      ["Observação / medida", c.observation],
                      ["Inicial", c.initial],
                      ["Atual", c.current],
                      ["Próxima ação", c.nextAction],
                    ].map(([label, value]) => (
                      <View key={label} style={{ marginTop: 8 }}>
                        <Label size={11} muted>
                          {label}
                        </Label>
                        <Label>{value || "—"}</Label>
                      </View>
                    ))}
                  </Card>
                ))}
            </>
          )}
          {!readonly && (
            <View style={s.row}>
              <Button variant="secondary" onPress={() => onEdit(r)}>
                Editar registro
              </Button>
              <Button variant="danger" onPress={() => onDelete(r)}>
                Excluir registro
              </Button>
            </View>
          )}
        </Section>
      ))}
    </>
  );
}

function RecordList({
  records,
  readonly,
  onAdd,
  onEdit,
  onDelete,
}: {
  records: TrackingRecord[];
  readonly: boolean;
  onAdd: () => void;
  onEdit: (r: TrackingRecord) => void;
  onDelete: (r: TrackingRecord) => void;
}) {
  const [expanded, setExpanded] = useState("");
  if (!records.length)
    return (
      <Empty
        title="Nenhum registro neste período"
        description="Os próximos registros formarão o histórico de evolução."
        action={
          !readonly ? (
            <Button variant="secondary" onPress={onAdd}>
              Adicionar registro
            </Button>
          ) : undefined
        }
      />
    );
  return (
    <>
