              </View>
            ))}
          </Card>
        </>
      )}
      {editing && (
        <Dialog title="Editar cadastro" onClose={() => setEditing(false)}>
          <StudentForm
            student={student}
            programs={programs ?? []}
            onSaved={() => {
              setEditing(false);
              void reload();
            }}
          />
        </Dialog>
      )}
      {record && (
        <Dialog
          title={recordNames[record.kind]}
          onClose={() => setRecord(null)}
