            onSaved={() => {
              setRecord(null);
              void reload();
            }}
          />
        </Dialog>
      )}
      {evaluation && (
        <Dialog
          title="Avaliação periódica"
          onClose={() => {
            setEvaluation(null);
            void reload();
          }}
