  error = false,
}: {
  children: ReactNode;
  error?: boolean;
}) {
  const t = useTheme();
  return children ? (
    <View
      accessibilityRole={error ? "alert" : "text"}
      style={{
        padding: 14,
        borderRadius: 10,
        backgroundColor: error ? t.accentSoft : t.backgroundElement,
        marginVertical: 10,
      }}
    >
      <Text
        style={{
          color: error ? t.danger : t.textSecondary,
          fontSize: 13,
          lineHeight: 20,
        }}
      >
        {children}
      </Text>
    </View>
  ) : null;
}

