    (e) =>
      e.status === status &&
      (!onlyFavorites || isFavorite(e)) &&
      normalize(e.name).includes(normalize(search)) &&
      normalize(e.muscleGroup).includes(normalize(muscle)) &&
      normalize(e.category).includes(normalize(category)),
  );
