}) {
  const [open, setOpen] = useState(false);
  const [comment, setComment] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  // Identifica uma tentativa de envio, inclusive quando a resposta se perde na rede.
  const [requestId, setRequestId] = useState(() => `${Date.now()}-${Math.random().toString(36).slice(2)}`);
  const feedbacks = workout.feedbacks ?? [];
  const completed=(workout.completions??[]).some(item=>item.completedOn===brazilToday());
  async function complete(){
    setBusy(true);setError("");
    try{await api(`/me/workouts/${workout.id}/completion`,"POST",{});setSuccess("Treino concluído! Seu personal foi avisado.");await reload();}
    catch(error){setError(message(error));}finally{setBusy(false);}
  }
  async function send() {
    const parsed = workoutFeedbackSchema.safeParse({ comment, requestId });
    if (!parsed.success) { setError(parsed.error.issues[0].message); return; }
    setBusy(true);
    setError("");
    try {
      await api(`/me/workouts/${workout.id}/feedbacks`, "POST", parsed.data);
      setComment("");
      setRequestId(`${Date.now()}-${Math.random().toString(36).slice(2)}`);
      setSuccess("Feedback registrado e disponível para o personal.");
      await reload();
    } catch (e) { setError(message(e)); }
    finally { setBusy(false); }
  }
  if (open) return <WorkoutScreen title={`Feedbacks · ${workout.name}`} backLabel="Voltar aos treinos" back={() => { if (!busy) setOpen(false); }}>
      <View style={{ gap: 12 }}>
        {canSend && <>
          <Label>Após terminar o treino, conte ao personal como foi sua experiência.</Label>
          <Field label="Seu feedback" value={comment} onChangeText={setComment} multiline maxLength={2000} editable={!busy} />
          <Button disabled={busy || !comment.trim()} onPress={() => void send()}>{busy ? "Enviando…" : "Registrar feedback"}</Button>
        </>}
        <Notice error>{error}</Notice>
        <Notice>{success}</Notice>
        {!feedbacks.length && <Notice>Nenhum feedback registrado para este treino.</Notice>}
        {feedbacks.map(feedback => <Card key={feedback.id}>
          <Label size={12} muted>{new Date(feedback.createdAt).toLocaleString("pt-BR")}</Label>
          <Label>{feedback.comment}</Label>
          {!!feedback.photo&&<Image source={{uri:feedback.photo}} accessibilityLabel="Foto do treino" style={{width:'100%',height:240}} resizeMode="contain"/>}
        </Card>)}
      </View>
    </WorkoutScreen>;
  return <>
    <Button variant="secondary" onPress={() => { setOpen(true); setSuccess(""); }}>
      Feedbacks ({feedbacks.length})
    </Button>
    {canSend && <>
      <Pressable accessibilityRole="checkbox" accessibilityLabel="Concluir treino de hoje" accessibilityState={{checked:completed,disabled:busy||completed}}
        disabled={busy||completed} onPress={()=>void complete()} style={{padding:14,minHeight:48,borderRadius:10,borderWidth:1,borderColor:completed?"#22c55e":"#888"}}>
        <Label bold>{completed?"✓ Treino de hoje concluído":busy?"Registrando…":"☐ Concluir treino de hoje"}</Label>
      </Pressable>
      <Notice error>{error}</Notice><Notice>{success}</Notice>
      <Button variant="secondary" onPress={() => { setOpen(true); setSuccess(""); }}>Terminei: enviar feedback</Button>
    </>}
  </>;
}

