      <View style={{ gap: 12 }}>
        <View><Label size={12} bold>Status da rotina</Label><Label size={13}>{plan.status === "ativo" ? "Ativa" : plan.status === "rascunho" ? "Rascunho" : "Arquivada"}</Label></View>
