export function WorkoutPlans({
  studentId,
  studentView = false,
  route,
}: {
  route?: WorkoutRoute;
  studentId?: string;
  studentView?: boolean;
}) {
  const { data, loading, error, reload } = useResource<Plan[]>(
    studentView ? "/me/workout-plans" : `/students/${studentId}/workout-plans`,
  );
  const t = useTheme();
  const [section, setSection] = useState("Rotinas de treino");
  const [filter, setFilter] = useState("Todas");
  const [localSelected, setLocalSelected] = useState<string | null>(null);
  const selected = route ? route.planId ?? null : localSelected;
  const setSelected = (id: string | null) => route ? route.selectPlan(id ?? undefined) : setLocalSelected(id);
  const [actions, setActions] = useState<Plan | null>(null);
  const [initialGroup, setInitialGroup] = useState<string | undefined>();
  const [initialPicker, setInitialPicker] = useState(false);
  const [initialTemplatePicker, setInitialTemplatePicker] = useState(false);
  const [initialWorkout, setInitialWorkout] = useState<number | null>(null);
  const [addingWorkout, setAddingWorkout] = useState(false);
  const [editing, setEditing] = useState<Plan | "new" | null>(null);
  const [programPicker, setProgramPicker] = useState(false);
  const [programData, setProgramData] = useState<PlanData | undefined>();
  const programs = useResource<Program[]>(programPicker ? "/programs" : null);
  const [archive, setArchive] = useState<Plan | null>(null);
  const [publish, setPublish] = useState<Plan | null>(null);
  const [discard, setDiscard] = useState(false);
  const [childScreen, setChildScreen] = useState(false);
  const [success, setSuccess] = useState("");
  const plans =
    data?.filter((p) => !studentId || p.studentId === studentId) ?? [];
  const selectedPlan = plans.find(p => p.id === selected);
  const visible = plans.filter(p => {
    if (section === "Arquivadas") return p.status === "arquivado";
    if (p.status === "arquivado") return false;
    if (filter === "Rascunhos") return p.status === "rascunho";
    if (filter === "Atuais") return p.status === "ativo" && p.startsAt <= today() && (!p.endsAt || p.endsAt >= today());
    if (filter === "Futuras") return p.status === "ativo" && p.startsAt > today();
    if (filter === "Encerradas") return p.status === "ativo" && !!p.endsAt && p.endsAt < today();
    return true;
  });
  if (editing && studentId) return <>
        <WorkoutScreen
          hideHeader={childScreen}
          title={addingWorkout ? "Adicionar treino" : editing === "new" ? "Criar plano" : "Editar plano"}
          backLabel="Voltar à rotina"
          back={() => setDiscard(true)}
        >
          <PlanForm
            initialData={programData}
            addingWorkout={addingWorkout}
            screenChanged={setChildScreen}
            studentId={studentId}
            initialWorkout={initialWorkout}
            initialPicker={initialPicker}
            initialGroup={initialGroup}
            initialTemplatePicker={initialTemplatePicker}
            plan={editing === "new" ? undefined : editing}
            cancel={() => setDiscard(true)}
            done={(saved) => {
              if (editing === "new") {
                setSection("Rotinas de treino");
                setFilter("Todas");
                setSelected(null);
              }
              setInitialWorkout(null); setInitialPicker(false); setInitialGroup(undefined);
              setInitialTemplatePicker(false);
              setEditing(null);
              setProgramData(undefined);
              setAddingWorkout(false);
              setSuccess(saved.status === "rascunho" ? "Rascunho salvo. O aluno ainda não vê os treinos. Toque em Liberar para o aluno quando estiver pronto." : saved.status === "ativo" ? "Rotina salva e liberada para o aluno." : "Plano arquivado salvo.");
              void reload();
            }}
          />
        </WorkoutScreen>
      {discard && (
        <Confirm
          title="Descartar alterações não salvas?"
          description={addingWorkout ? "O novo treino ainda não foi salvo." : "As alterações do plano ainda não foram enviadas."}
          onClose={() => setDiscard(false)}
          onConfirm={async () => { setEditing(null); setProgramData(undefined); setAddingWorkout(false); setInitialWorkout(null); setInitialPicker(false); setInitialTemplatePicker(false); }}
        />
      )}
  </>;
  return (
    <View style={{ gap: 12 }}>
      <Notice>{success}</Notice>
      <Notice error>{error}</Notice>
      {loading && <Notice>Carregando rotinas…</Notice>}
      {error && <Button onPress={() => void reload()}>Tentar novamente</Button>}
      {selectedPlan ? <>
        {!route?.workoutId && <View style={{ alignSelf: "flex-start" }}><Button variant="secondary" onPress={() => setSelected(null)}>‹ Todas as rotinas</Button></View>}
        <PlanDetails key={selectedPlan.id} route={route} plan={selectedPlan} studentView={studentView} reload={reload}
          editWorkout={studentView ? undefined : (index, picker, groupId) => {
            setInitialGroup(groupId);
            setInitialWorkout(index); setInitialPicker(picker); setEditing(selectedPlan);
          }}
          add={studentView ? undefined : () => {
            setAddingWorkout(true);
            setInitialWorkout(selectedPlan.workouts.length);
            setEditing({ ...selectedPlan, workouts: [...selectedPlan.workouts, {
              name: `Treino ${String.fromCharCode(65 + selectedPlan.workouts.length)}`,
              subtitle: "", instructions: "", exercises: [],
            }] });
          }} edit={studentView ? undefined : () => setEditing(selectedPlan)}
          archive={studentView ? undefined : () => setArchive(selectedPlan)} />
      </> : <>
        <View style={{ flexDirection: "row", gap: 6 }}>
          {["Rotinas de treino", "Arquivadas"].map(value => <Pressable key={value} accessibilityRole="tab" accessibilityLabel={value}
            aria-selected={section === value} onPress={() => setSection(value)}
            style={{ flex: 1, minHeight: 44, justifyContent: "center", alignItems: "center", borderRadius: 6,
              backgroundColor: section === value ? t.accentSoft : t.backgroundElement,
              borderBottomWidth: 3, borderBottomColor: section === value ? t.accent : "transparent" }}>
            <Label size={13} bold>{value}</Label>
          </Pressable>)}
        </View>
        <View style={{ backgroundColor: t.backgroundElement, borderRadius: 8, padding: 12, gap: 12 }}>
          {!studentView && <Pressable accessibilityRole="button" accessibilityLabel="Criar rotina" onPress={() => setEditing("new")}
            style={{ minHeight: 52, alignItems: "center", justifyContent: "center", borderWidth: 1, borderColor: t.accent, backgroundColor: t.background, borderRadius: 6 }}>
            <Label size={14} bold>+ Criar rotina</Label>
          </Pressable>}
          {!studentView && <Button variant="secondary" onPress={() => { setInitialTemplatePicker(true); setEditing("new"); }}>Usar treino</Button>}
          {!studentView && <Button variant="secondary" onPress={() => setProgramPicker(true)}>Usar rotina de Programas</Button>}
          {section !== "Arquivadas" && <View style={{ flexDirection: "row", flexWrap: "wrap", gap: 6 }}>
            {["Todas", "Atuais", "Futuras", "Encerradas", ...(!studentView ? ["Rascunhos"] : [])].map(value =>
              <Pressable key={value} accessibilityRole="button" accessibilityLabel={`Filtrar rotinas: ${value}`} aria-pressed={filter === value}
                onPress={() => setFilter(value)} style={{ minHeight: 36, paddingHorizontal: 10, justifyContent: "center", borderRadius: 5, backgroundColor: filter === value ? t.accentSoft : t.background }}>
                <Label size={12}>{value}</Label>
              </Pressable>)}
          </View>}
          {!loading && !error && !visible.length && <Notice>{section === "Arquivadas" ? "Nenhuma rotina arquivada." : "Nenhuma rotina neste filtro."}</Notice>}
          {visible.map(plan => <PlanCard key={plan.id} plan={plan} onOpen={() => setSelected(plan.id)}
            onPublish={!studentView && plan.status === "rascunho" ? () => setPublish(plan) : undefined}
            onActions={studentView ? undefined : () => setActions(plan)} />)}
        </View>
      </>}
      {programPicker && <Dialog title="Escolher rotina" onClose={() => setProgramPicker(false)}>
        <Notice error>{programs.error}</Notice>
        {programs.loading && <Notice>Carregando rotinas…</Notice>}
        {programs.error && <Button onPress={() => void programs.reload()}>Tentar novamente</Button>}
        {!programs.loading && !programs.error && !programs.data?.length && <Notice>Crie uma rotina com treinos na página Programas.</Notice>}
        {programs.data?.map(program => <Card key={program.id}>
          <Label bold>{program.name}</Label><Label muted>{program.workouts?.length ?? 0} treino(s)</Label>
          <Button disabled={!program.workouts?.length || program.workouts.some(w => w.exercises.some(e => !e.exercise || e.exercise.status !== "ativo" || e.alternativeExerciseId && (!e.alternativeExercise || e.alternativeExercise.status !== "ativo")))} label={`Usar rotina ${program.name}`} onPress={() => {
            setProgramData({ title: program.name, objective: program.description || "Adaptação", difficulty: "Iniciante", startsAt: today(), endsAt: null, instructions: program.sessions, status: "rascunho", workouts: program.workouts!.map(copyPreparedWorkout) });
            setProgramPicker(false); setEditing("new");
          }}>Usar esta rotina</Button>
        </Card>)}
      </Dialog>}
      {actions && <Dialog title={actions.title} onClose={() => setActions(null)}>
        <View style={{ gap: 12 }}>
          <Button variant="secondary" onPress={() => { setSelected(actions.id); setActions(null); }}>Ver treinos</Button>
          <Button onPress={() => { setEditing(actions); setActions(null); }}>Editar plano</Button>
          {actions.status !== "arquivado" && <Button variant="secondary" onPress={() => { setArchive(actions); setActions(null); }}>Arquivar plano</Button>}
        </View>
      </Dialog>}
      {archive && (
        <Confirm
          title="Arquivar plano?"
          description="O plano sairá dos planos ativos. O histórico publicado permanece disponível ao aluno."
          onClose={() => setArchive(null)}
          onConfirm={async () => {
            await api(`/workout-plans/${archive.id}`, "PUT", {
              ...archive,
              status: "arquivado",
            });
            setSuccess("Plano arquivado.");
            await reload();
          }}
        />
      )}
      {publish && <Confirm
        title="Liberar rotina para o aluno?"
        description="O aluno vinculado poderá consultar todos os treinos desta rotina."
        onClose={() => setPublish(null)}
        onConfirm={async () => {
          await api(`/workout-plans/${publish.id}`, "PUT", { ...publish, status: "ativo" });
          setSuccess("Rotina liberada para o aluno.");
          await reload();
        }}
      />}
    </View>
  );
}

