    const copy = { ...item, id: undefined, clientId: nextOccurrenceKey(), series: item.series.map(row => ({ ...row })) };
    const next = [...items]; next.splice(items.indexOf(item) + 1, 0, copy);
    void apply(next, "duplicate").catch(() => {});
