export function SessionProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const refresh = useCallback(async () => {
    try {
      const result = await api<{ user: User | null }>("/auth/status");
      setUser(result.user);
      setError("");
    } catch (e) {
      setError(message(e));
    } finally {
      setLoading(false);
    }
  }, []);
  useEffect(() => {
    void refresh();
  }, [refresh]);
  async function authenticate(action: "login" | "register", data: unknown, onAuthenticated?: () => Promise<void>) {
    const result = await api<{ user: User; token?: string }>(
      `/auth/${action}`,
      "POST",
      data,
    );
    if (result.token) await saveSession(result.token);
    // Preferências de preenchimento não impedem um acesso já validado pela API.
    await onAuthenticated?.().catch(() => {});
    setUser(result.user);
    setError("");
  }
  async function logout() {
    await clearNotificationsDevice().catch(() => {});
    await api("/auth/logout", "POST");
    await saveSession(null);
    setUser(null);
  }
  return (
    <Context.Provider
      value={{ user, loading, error, refresh, authenticate, logout }}
    >
      {children}
    </Context.Provider>
  );
}

